# Check girth using BFS from each vertex
from collections import deque

def find_shortest_cycle(adj, n):
    min_cycle = float('inf')
    for start in range(n):
        # BFS to find shortest cycle through start
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

girth = find_shortest_cycle(adj, n)
print(f"\nGirth: {girth}")
if girth >= 7:
    print("VALID SOLUTION!")
else:
    print("INVALID - girth too small")
